import requests, time, json
import pandas as pd

headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"}

def try_tencent():
    url = "https://web.ifzq.gtimg.cn/appstock/app/fqkline/get"
    params = {"param": "sh600519,day,2025-06-01,2026-12-31,400,qfq"}
    r = requests.get(url, params=params, headers=headers, timeout=30)
    j = r.json()
    node = j["data"]["sh600519"]
    key = "qfqday" if "qfqday" in node else "day"
    days = node[key]
    rows = []
    for d in days:
        # Tencent: [date, open, close, high, low, volume, ...]
        rows.append({"date": d[0], "open": float(d[1]), "close": float(d[2]),
                     "high": float(d[3]), "low": float(d[4]), "volume": float(d[5])})
    df = pd.DataFrame(rows)
    df["date"] = pd.to_datetime(df["date"])
    return df.sort_values("date").reset_index(drop=True)

def try_sina():
    url = "https://quotes.sina.cn/cn/api/json_v2.php/CN_MarketDataService.getKLineData"
    params = {"symbol": "sh600519", "scale": "240", "ma": "no", "datalen": "320"}
    r = requests.get(url, params=params, headers=headers, timeout=30)
    j = r.json()
    rows = []
    for d in j:
        rows.append({"date": d["day"], "open": float(d["open"]), "close": float(d["close"]),
                     "high": float(d["high"]), "low": float(d["low"]), "volume": float(d["volume"])})
    df = pd.DataFrame(rows)
    df["date"] = pd.to_datetime(df["date"])
    return df.sort_values("date").reset_index(drop=True)

for name, fn in [("tencent", try_tencent), ("sina", try_sina)]:
    try:
        df = fn()
        print(f"[{name}] OK rows={len(df)} range={df['date'].min().date()} -> {df['date'].max().date()}")
        print(df.head(2).to_string())
        print(df.tail(2).to_string())
    except Exception as e:
        print(f"[{name}] FAIL: {type(e).__name__}: {e}")
"}
